public sealed class CustomLocalizer(IStringLocalizer<Resources> localizer) : ITmLocalizer
{
    public CultureInfo Culture => CultureInfo.CurrentUICulture;

    public string this[string key] => localizer[key];

    public string this[string key, params object[] arguments]
        => string.Format(Culture, this[key], arguments);

    public bool TryGetString(string key, out string value)
    {
        var found = localizer[key];
        value = found.ResourceNotFound ? string.Empty : found.Value;
        return !found.ResourceNotFound;
    }
}

// Program.cs
builder.Services.AddSingleton<ITmLocalizer, CustomLocalizer>();

// Or use built-in
builder.Services.AddTempoBlazor(); // Registers default localizer

// Program.cs — the LAST ITmLocalizer registration wins, because AddTempoBlazor() uses TryAddSingleton.
builder.Services.AddTempoBlazor();
builder.Services.AddSingleton<ITmLocalizer, AppTranslationOverrideLocalizer>();

// AppTranslationOverrideLocalizer.cs
using System.Globalization;
using Microsoft.Extensions.Localization;
using Tempo.Blazor.Localization;
using Tempo.Blazor.Resources;

/// <summary>
/// Wraps the built-in localizer and rewords only the keys the application cares about;
/// everything else falls through to the shipped resources (en/cs/sk/fr) untouched.
/// </summary>
public sealed class AppTranslationOverrideLocalizer(IStringLocalizer<TmResources> builtIn) : ITmLocalizer
{
    private readonly Dictionary<string, string> _overrides = new()
    {
        ["TmDataTable_SaveView"] = "Uložit pohled jako…",
        ["Tm_Search"] = "Hledat…",
        ["TmModelingIssuePanel_Count_One"] = "Celkem {0} nález",
    };

    public CultureInfo Culture => CultureInfo.CurrentUICulture;

    public string this[string key] =>
        _overrides.TryGetValue(key, out var value) ? value : builtIn[key].Value;

    public string this[string key, params object[] arguments] =>
        _overrides.TryGetValue(key, out var value)
            ? string.Format(Culture, value, arguments)
            : builtIn[key, arguments].Value;
}

